function EPanitiaOverlay({children,onClose,...props}:React.HTMLAttributes<HTMLDivElement>&{onClose:()=>void}){
 const root=useRef<HTMLDivElement|null>(null);
 useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const dialog=root.current;const first=dialog?.querySelector<HTMLElement>('button,a[href],input,select,textarea,summary');first?.focus();const key=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();onClose();return;}if(event.key!=='Tab'||!dialog)return;const controls=Array.from(dialog.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary')).filter(x=>x.getClientRects().length);const start=controls[0],end=controls[controls.length-1];if(event.shiftKey&&document.activeElement===start){event.preventDefault();end?.focus();}else if(!event.shiftKey&&document.activeElement===end){event.preventDefault();start?.focus();}};dialog?.addEventListener('keydown',key);return()=>{dialog?.removeEventListener('keydown',key);if(previous?.isConnected)previous.focus({preventScroll:true});};},[]);
 return createPortal(<div {...props} ref={root} className="epanitia-detail-backdrop" role="dialog" aria-modal="true" aria-label="Butiran e-Panitia">{children}</div>,document.body);
}
function Input({label,value,onChange,type="text",required=false,placeholder=""}:{label:string;value:any;onChange:(v:any)=>void;type?:string;required?:boolean;placeholder?:string}){return <label><span>{label}{required&&<b className="required"> *</b>}</span><input type={type} value={value??""} onChange={e=>onChange(type==="number"?Number(e.target.value):e.target.value)} placeholder={placeholder}/></label>}
