function People({label,items,onChange,users}:{label:string;items:string[];onChange:(v:string[])=>void;users:DirectoryUser[]}){return <fieldset className="builder-list"><legend>{label}</legend>{items.map((id,i)=><div className="builder-row people" key={i}><select value={id} onChange={e=>onChange(items.map((x,j)=>i===j?e.target.value:x))}><option value="">Pilih guru berdaftar</option>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select><button type="button" aria-label="Buang item" onClick={()=>onChange(items.filter((_,j)=>j!==i))}><Trash2/></button></div>)}<button type="button" className="builder-add" onClick={()=>onChange([...items,""])}>Tambah guru</button></fieldset>}
